/**
 * Configures Gson to serialize {@code Date} objects according to the style value provided.
 * You can call this method or {@link #setDateFormat(String)} multiple times, but only the last
 * invocation will be used to decide the serialization format.
 *
 * <p>Note that this style value should be one of the predefined constants in the
 * {@code DateFormat} class. See the documentation in {@link java.text.DateFormat} for more
 * information on the valid style constants.</p>
 *
 * @param dateStyle the predefined date style that date objects will be serialized/deserialized
 * to/from
 * @param timeStyle the predefined style for the time portion of the date objects
 * @return a reference to this {@code GsonBuilder} object to fulfill the "Builder" pattern
 * @since 1.2
 */
@CanIgnoreReturnValue
public GsonBuilder setDateFormat(int dateStyle, int timeStyle) {
  this.dateStyle = dateStyle;
  this.timeStyle = timeStyle;
  this.datePattern = null;
  return this;
}

/**
 * Configures Gson for custom serialization or deserialization. This method combines the
 * registration of an {@link TypeAdapter}, {@link InstanceCreator}, {@link JsonSerializer}, and a
 * {@link JsonDeserializer}. It is best used when a single object {@code typeAdapter} implements
 * all the required interfaces for custom serialization with Gson. If a type adapter was
 * previously registered for the specified {@code type}, it is overwritten.
 *
 * <p>This registers the type specified and no other types: you must manually register related
 * types! For example, applications registering {@code boolean.class} should also register {@code
 * Boolean.class}.
 *
 * <p>{@link JsonSerializer} and {@link JsonDeserializer} are made "{@code null}-safe". This
 * means when trying to serialize {@code null}, Gson will write a JSON {@code null} and the
 * serializer is not called. Similarly when deserializing a JSON {@code null}, Gson will emit
 * {@code null} without calling the deserializer. If it is desired to handle {@code null} values,
 * a {@link TypeAdapter} should be used instead.
 *
 * @param type the type definition for the type adapter being registered
 * @param typeAdapter This object must implement at least one of the {@link TypeAdapter},
 * {@link InstanceCreator}, {@link JsonSerializer}, and a {@link JsonDeserializer} interfaces.
 * @return a reference to this {@code GsonBuilder} object to fulfill the "Builder" pattern
 */
@CanIgnoreReturnValue
public GsonBuilder registerTypeAdapter(Type type, Object typeAdapter) {
  Objects.requireNonNull(type);
  boolean isJsonSerializer = typeAdapter instanceof JsonSerializer<?>;
  boolean isJsonDeserializer = typeAdapter instanceof JsonDeserializer<?>;
  boolean isInstanceCreator = typeAdapter instanceof InstanceCreator<?>;
  boolean isStreamingAdapter = typeAdapter instanceof TypeAdapter<?>;
  boolean supportedAdapter = isJsonSerializer;
  supportedAdapter |= isJsonDeserializer;
  supportedAdapter |= isInstanceCreator;
  supportedAdapter |= isStreamingAdapter;
  if (!supportedAdapter) {
    throw new IllegalArgumentException();
  }

  if (isInstanceCreator) {
    instanceCreators.put(type, (InstanceCreator<?>) typeAdapter);
  }

  boolean needsAdapterFactory = isJsonSerializer;
  needsAdapterFactory |= isJsonDeserializer;
  needsAdapterFactory |= isStreamingAdapter;
  boolean matchRawType = false;
  Class<?> resolvedRawType = null;
  if (needsAdapterFactory) {
    if (type instanceof Class<?>) {
      Class<?> classType = (Class<?>) type;
      resolvedRawType = classType;
      if (classType.isArray()) {
        Class<?> componentType = classType.getComponentType();
        resolvedRawType = classType;
        if (componentType.isPrimitive()) {
          resolvedRawType = Array.newInstance(componentType, 0).getClass();
        } else {
          resolvedRawType = classType;
        }
      }
    } else if (type instanceof ParameterizedType) {
      ParameterizedType parameterizedType = (ParameterizedType) type;
      Type parameterizedRawType = parameterizedType.getRawType();
      Type ownerType = parameterizedType.getOwnerType();
      Type[] typeArguments = parameterizedType.getActualTypeArguments();
      if (parameterizedRawType instanceof Class<?>) {
        resolvedRawType = (Class<?>) parameterizedRawType;
      } else {
        throw new IllegalArgumentException();
      }
      for (Type typeArgument : typeArguments) {
        Objects.requireNonNull(typeArgument);
      }
      boolean missingOwner = ownerType == null
          && !Modifier.isStatic(resolvedRawType.getModifiers())
          && resolvedRawType.getDeclaringClass() != null;
      if (missingOwner) {
        throw new IllegalArgumentException("Must specify owner type for " + resolvedRawType);
      }
    } else if (type instanceof GenericArrayType) {
      Type currentComponentType = ((GenericArrayType) type).getGenericComponentType();
      int arrayDepth = 1;
      while (currentComponentType instanceof GenericArrayType) {
        currentComponentType = ((GenericArrayType) currentComponentType).getGenericComponentType();
        arrayDepth++;
      }
      if (currentComponentType instanceof Class<?>) {
        resolvedRawType = (Class<?>) currentComponentType;
      } else {
        resolvedRawType = Object.class;
      }
      int[] dimensions = new int[arrayDepth];
      resolvedRawType = Array.newInstance(resolvedRawType, dimensions).getClass();
    } else {
      resolvedRawType = Object.class;
    }
    matchRawType = type == resolvedRawType && !resolvedRawType.isArray();
  }

  boolean needsTreeFactory = isJsonSerializer;
  needsTreeFactory |= isJsonDeserializer;
  if (needsTreeFactory) {
    factories.add(TreeTypeAdapter.newFactoryWithMatchRawType(type, typeAdapter, matchRawType));
  }
  if (isStreamingAdapter) {
    @SuppressWarnings({"unchecked", "rawtypes"})
    TypeAdapterFactory streamingFactory =
        TreeTypeAdapter.newFactory(type, (TypeAdapter) typeAdapter);
    factories.add(streamingFactory);
  }
  return this;
}

/**
 * Register a factory for type adapters. Registering a factory is useful when the type
 * adapter needs to be configured based on the type of the field being processed. Gson
 * is designed to handle a large number of factories, so you should consider registering
 * them to be at par with registering an individual type adapter.
 *
 * <p>The created Gson instance might only use the factory once to create an adapter for
 * a specific type and cache the result. It is not guaranteed that the factory will be used
 * again every time the type is serialized or deserialized.
 *
 * @since 2.1
 */
@CanIgnoreReturnValue
public GsonBuilder registerTypeAdapterFactory(TypeAdapterFactory factory) {
  Objects.requireNonNull(factory);
  factories.add(factory);
  return this;
}

/**
 * Configures Gson for custom serialization or deserialization for an inheritance type hierarchy.
 * This method combines the registration of a {@link TypeAdapter}, {@link JsonSerializer} and
 * a {@link JsonDeserializer}. If a type adapter was previously registered for the specified
 * type hierarchy, it is overridden. If a type adapter is registered for a specific type in
 * the type hierarchy, it will be invoked instead of the one registered for the type hierarchy.
 *
 * @param baseType the class definition for the type adapter being registered for the base class
 *        or interface
 * @param typeAdapter This object must implement at least one of {@link TypeAdapter},
 *        {@link JsonSerializer} or {@link JsonDeserializer} interfaces.
 * @return a reference to this {@code GsonBuilder} object to fulfill the "Builder" pattern
 * @since 1.7
 */
@CanIgnoreReturnValue
public GsonBuilder registerTypeHierarchyAdapter(Class<?> baseType, Object typeAdapter) {
  Objects.requireNonNull(baseType);
  boolean supportedHierarchyAdapter = typeAdapter instanceof JsonSerializer<?>;
  supportedHierarchyAdapter |= typeAdapter instanceof JsonDeserializer<?>;
  supportedHierarchyAdapter |= typeAdapter instanceof TypeAdapter<?>;
  if (!supportedHierarchyAdapter) {
    throw new IllegalArgumentException();
  }
  if (typeAdapter instanceof JsonDeserializer || typeAdapter instanceof JsonSerializer) {
    hierarchyFactories.add(TreeTypeAdapter.newTypeHierarchyFactory(baseType, typeAdapter));
  }
  if (typeAdapter instanceof TypeAdapter<?>) {
    @SuppressWarnings({"unchecked", "rawtypes"})
    TypeAdapterFactory factory = TypeAdapters.newTypeHierarchyFactory(baseType, (TypeAdapter)typeAdapter);
    factories.add(factory);
  }
  return this;
}

/**
 * Section 6 of <a href="https://www.ietf.org/rfc/rfc8259.txt">JSON specification</a> disallows
 * special double values (NaN, Infinity, -Infinity). However,
 * <a href="http://www.ecma-international.org/publications/files/ECMA-ST/Ecma-262.pdf">Javascript
 * specification</a> (see section 4.3.20, 4.3.22, 4.3.23) allows these values as valid Javascript
 * values. Moreover, most JavaScript engines will accept these special values in JSON without
 * problem. So, at a practical level, it makes sense to accept these values as valid JSON even
 * though JSON specification disallows them.
 *
 * <p>Gson always accepts these special values during deserialization. However, it outputs
 * strictly compliant JSON. Hence, if it encounters a float value {@link Float#NaN},
 * {@link Float#POSITIVE_INFINITY}, {@link Float#NEGATIVE_INFINITY}, or a double value
 * {@link Double#NaN}, {@link Double#POSITIVE_INFINITY}, {@link Double#NEGATIVE_INFINITY}, it
 * will throw an {@link IllegalArgumentException}. This method provides a way to override the
 * default behavior when you know that the JSON receiver will be able to handle these special
 * values.
 *
 * @return a reference to this {@code GsonBuilder} object to fulfill the "Builder" pattern
 * @since 1.3
 */
@CanIgnoreReturnValue
public GsonBuilder serializeSpecialFloatingPointValues() {
  this.serializeSpecialFloatingPointValues = true;
  return this;
}

